-- name: GetGithubInstallation :one
SELECT * FROM github_installations WHERE id = $1;

-- name: ListGithubInstallations :many
SELECT * FROM github_installations ORDER BY created_at DESC LIMIT $1 OFFSET $2;

-- name: CreateGithubInstallation :one
INSERT INTO github_installations (team_id, installation_id, account_login, account_type, repository_selection, installed_by, suspended_at)
VALUES ($1, $2, $3, $4, $5, $6, $7)
RETURNING *;

-- name: DeleteGithubInstallation :exec
DELETE FROM github_installations WHERE id = $1;

-- Hosbah queries.

-- name: GitHubInstallationsOfTeam :many
-- Team scope: the team's GitHub App installations.
SELECT * FROM github_installations WHERE team_id = $1 ORDER BY lower(account_login), installation_id;

-- name: GitHubInstallationByInstallationID :one
-- System scope (the setup callback and webhooks): whichever team holds it.
SELECT * FROM github_installations WHERE installation_id = $1;

-- name: UpsertGitHubInstallation :one
-- Stores what GitHub confirmed. An installation another team holds is never taken over: the update
-- only applies to the same team's row, so a foreign row returns nothing (sql.ErrNoRows).
INSERT INTO github_installations (team_id, installation_id, account_login, account_type, repository_selection, installed_by, suspended_at)
VALUES (sqlc.arg('team_id'), sqlc.arg('installation_id'), sqlc.arg('account_login'), sqlc.arg('account_type'),
    sqlc.arg('repository_selection'), sqlc.arg('installed_by'), sqlc.narg('suspended_at'))
ON CONFLICT (installation_id) DO UPDATE SET account_login = EXCLUDED.account_login, account_type = EXCLUDED.account_type,
    repository_selection = EXCLUDED.repository_selection, suspended_at = EXCLUDED.suspended_at, updated_at = now()
WHERE github_installations.team_id = EXCLUDED.team_id
RETURNING *;

-- name: SetGitHubInstallationSuspended :one
UPDATE github_installations SET suspended_at = sqlc.narg('suspended_at'), updated_at = now()
WHERE installation_id = sqlc.arg('installation_id') RETURNING team_id;

-- name: SetGitHubInstallationSelection :one
UPDATE github_installations SET repository_selection = sqlc.arg('repository_selection'), updated_at = now()
WHERE installation_id = sqlc.arg('installation_id') RETURNING team_id;

-- name: DeleteGitHubInstallationByInstallationID :one
DELETE FROM github_installations WHERE installation_id = $1 RETURNING team_id;

-- name: RecordGitHubDelivery :execrows
-- 1 the first time a delivery id is seen, 0 for a redelivery.
INSERT INTO github_deliveries (delivery_id, event) VALUES ($1, $2) ON CONFLICT (delivery_id) DO NOTHING;

-- name: PruneGitHubDeliveries :exec
DELETE FROM github_deliveries WHERE received_at < now() - interval '30 days';
